pub type MermanNativeEngineNewFn = unsafe extern "C" fn(
    config: *const MermanNativeEngineConfig,
    out_engine: *mut MermanNativeEngineToken,
    out_result: *mut MermanNativeResult,
) -> MermanNativeStatus;
pub type MermanNativeEngineTryCloseFn =
    unsafe extern "C" fn(engine: MermanNativeEngineToken) -> MermanNativeStatus;
pub type MermanNativeExecuteCollectFn = unsafe extern "C" fn(
    engine: MermanNativeEngineToken,
    request: *const MermanNativeOperationRequest,
    out_result: *mut MermanNativeResult,
) -> MermanNativeStatus;
pub type MermanNativeResultFreeFn = unsafe extern "C" fn(result: *mut MermanNativeResult) -> ();
pub type MermanNativeMetadataCollectFn = unsafe extern "C" fn(
    metadata_id: MermanNativeSlice,
    out_result: *mut MermanNativeResult,
) -> MermanNativeStatus;

pub const MERMAN_NATIVE_API_MINIMUM_PREFIX_SIZE: u32 =
    (std::mem::offset_of!(MermanNativeApi, result_free)
        + std::mem::size_of::<Option<MermanNativeResultFreeFn>>()) as u32;

pub const MERMAN_NATIVE_API_METADATA_COLLECT_PREFIX_SIZE: u32 =
    (std::mem::offset_of!(MermanNativeApi, metadata_collect)
        + std::mem::size_of::<Option<MermanNativeMetadataCollectFn>>()) as u32;

pub const MERMAN_NATIVE_API_COMPLETE_PREFIX_SIZES: &[u32] = &[
    MERMAN_NATIVE_API_MINIMUM_PREFIX_SIZE,
    MERMAN_NATIVE_API_METADATA_COLLECT_PREFIX_SIZE,
];

pub const MERMAN_NATIVE_ABI_OWNERSHIP_RULES: &[(&str, &str)] = &[
    (
        "borrowed_slices",
        "Input, media-type, and callback slices are borrowed. Hosts must not retain their pointers after the enclosing call or callback returns.",
    ),
    (
        "disabled_capabilities",
        "A known operation whose backend is absent is rejected before backend work with unsupported_operation, kind missing-capability, and the canonical capability_id. An unknown operation code returns the same status with kind unknown-operation and a null capability_id. Both failures are written results with nonzero allocation_token values and must be released with result_free.",
    ),
    (
        "engine_tokens",
        "Engine tokens are opaque u64 values. engine_try_close never waits: callback-active returns reentrant-call, another active operation returns busy with the token still valid, and quiescent success permanently closes admission before retiring the token. A transport reference acquired before successful close cannot enter afterwards. Callback and user_data are immutable constructor-owned state and may be released after successful close.",
    ),
    (
        "host_callbacks",
        "Host callbacks are synchronous and borrowed for the call. They MUST NOT unwind, throw, propagate SEH, longjmp, or otherwise perform a non-local exit across the ABI boundary. Merman converts returned status values only; it cannot catch foreign exceptions.",
    ),
    (
        "result_buffers",
        "Only result.data and result.metadata_or_error_json identified by a live allocation_token are Merman-owned. Callers zero-initialize the complete result and set struct_size before every producing call. Merman assigns a process-lifetime monotonic nonzero token that is never reused. If token issuance is exhausted, the call returns internal-error and leaves the caller's valid zero-initialized result untouched because no conforming result can be written. Moving the complete record transfers ownership. result_free clears the supplied record before trusting its token to release the backing allocation, so a moved record may reside inside Merman-owned result storage. Zero, unknown, stale, and random non-live tokens release nothing and only clear the supplied record. Copying a live token is outside the same-process hostile-memory threat boundary. No result buffer may be passed to a host allocator.",
    ),
];
